tton{width:100%;margin-bottom:8px}.dismiss-button{display:block;margin:2px auto 0;border:0!important;color:#8996a4!important}.admitted-guests{border-top:1px solid #e5edf2;margin-top:12px;padding-top:12px}.admitted-guests h3{font-size:12px;color:#6a7f90}.admitted-guests p{font-size:13px;display:flex;gap:9px;align-items:center}.lobby-hint{font-size:12px;color:#7d704e;line-height:1.7}.office-notice{padding:12px 16px;background:#f3f7fb;border:1px solid #e0e8f0;border-radius:10px;font-size:12px;color:#5c748a}.office-error{padding:12px 16px;border-radius:10px;background:#fff3f3;color:#a12424}.end-button{margin-top:14px;color:#b83f4c!important}.history-scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:12px}td,th{padding:12px;text-align:left;border-bottom:1px solid #dae7e0}summary{cursor:pointer;padding:18px 0;color:#6c8195;font-size:12px}.history-files article{padding:14px;border:1px solid #dce5ed;border-radius:12px;margin:12px 0}.photo-dialog{position:fixed;inset:0;z-index:10000;border:1px solid #d5e4dc;border-radius:18px;box-shadow:0 0 0 100vmax #0009;max-width:min(90vw,720px);padding:24px}.photo-dialog img{display:block;width:100%;max-height:65vh;object-fit:contain}.same-session-confirm{position:fixed;z-index:10001;inset:30% auto auto 50%;transform:translateX(-50%);width:min(480px,85vw);background:white;padding:24px;border:1px solid #bad4ca;border-radius:16px;box-shadow:0 0 0 100vmax #0009}.same-session-confirm h2{font-size:20px}.same-session-confirm button{margin:6px}.private-office>p:last-child{font-size:11px;color:#92a0ac}@media(max-width:900px){.office-layout{grid-template-columns:minmax(0,1fr) 250px;gap:14px}.office-lobby{padding:15px}}@media(max-width:720px){.office-layout{grid-template-columns:1fr}.office-heading{align-items:flex-start;flex-direction:column;gap:12px}.office-link-bar{flex-wrap:wrap;gap:4px}.office-link-bar label{width:100%}.office-welcome{min-height:360px}.office-lobby{max-height:none}.office-header{gap:10px}.plan-badge{display:none}.private-office{padding:18px 14px}}
